window.__votdWeek && window.__votdWeek({"week":"2026-10-05","reading":"Isaiah 50–57","days":[{"d":"2026-10-05","ref":"Isaiah 51:5","b":"Isaiah","c":51,"v":5,"he":"קָרוֹב צִדְקִי יָצָא יִשְׁעִי וּזְרֹעַי עַמִּים יִשְׁפֹּטוּ אֵלַי אִיִּים יְקַוּוּ וְאֶל־זְרֹעִי יְיַחֵלוּן׃","en":"My righteousness is near; my salvation is gone forth, and mine arms shall judge the people; the isles shall wait upon me, and on mine arm shall they trust."},{"d":"2026-10-06","ref":"Isaiah 52:1","b":"Isaiah","c":52,"v":1,"he":"עוּרִי עוּרִי לִבְשִׁי עֻזֵּךְ צִיּוֹן לִבְשִׁי בִּגְדֵי תִפְאַרְתֵּךְ יְרוּשָׁלַ͏ִם עִיר הַקֹּדֶשׁ כִּי לֹא יוֹסִיף יָבֹא־בָךְ עוֹד עָרֵל וְטָמֵא׃","en":"Awake, awake; put on thy strength, O Zion; put on thy beautiful garments, O Jerusalem, the holy city: for henceforth there shall no more come into thee the uncircumcised and the unclean."},{"d":"2026-10-07","ref":"Isaiah 52:7","b":"Isaiah","c":52,"v":7,"he":"מַה־נָּאווּ עַל־הֶהָרִים רַגְלֵי מְבַשֵּׂר מַשְׁמִיעַ שָׁלוֹם מְבַשֵּׂר טוֹב מַשְׁמִיעַ יְשׁוּעָה אֹמֵר לְצִיּוֹן מָלַךְ אֱלֹהָיִךְ׃","en":"How beautiful upon the mountains are the feet of him that bringeth good tidings, that publisheth peace; that bringeth good tidings of good, that publisheth salvation; that saith unto Zion, Thy God reigneth!"},{"d":"2026-10-08","ref":"Isaiah 53:5","b":"Isaiah","c":53,"v":5,"he":"וְהוּא מְחֹלָל מִפְּשָׁעֵנוּ מְדֻכָּא מֵעֲוֺנֹתֵינוּ מוּסַר שְׁלוֹמֵנוּ עָלָיו וּבַחֲבֻרָתוֹ נִרְפָּא־לָנוּ׃","en":"But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed."},{"d":"2026-10-09","ref":"Isaiah 53:7","b":"Isaiah","c":53,"v":7,"he":"נִגַּשׂ וְהוּא נַעֲנֶה וְלֹא יִפְתַּח־פִּיו כַּשֶּׂה לַטֶּבַח יוּבָל וּכְרָחֵל לִפְנֵי גֹזְזֶיהָ נֶאֱלָמָה וְלֹא יִפְתַּח פִּיו׃","en":"He was oppressed, and he was afflicted, yet he opened not his mouth: he is brought as a lamb to the slaughter, and as a sheep before her shearers is dumb, so he openeth not his mouth."},{"d":"2026-10-10","ref":"Isaiah 55:1","b":"Isaiah","c":55,"v":1,"he":"הוֹי כׇּל־צָמֵא לְכוּ לַמַּיִם וַאֲשֶׁר אֵין־לוֹ כָּסֶף לְכוּ שִׁבְרוּ וֶאֱכֹלוּ וּלְכוּ שִׁבְרוּ בְּלוֹא־כֶסֶף וּבְלוֹא מְחִיר יַיִן וְחָלָב׃","en":"Ho, every one that thirsteth, come ye to the waters, and he that hath no money; come ye, buy, and eat; yea, come, buy wine and milk without money and without price."},{"d":"2026-10-11","ref":"Isaiah 55:7","b":"Isaiah","c":55,"v":7,"he":"יַעֲזֹב רָשָׁע דַּרְכּוֹ וְאִישׁ אָוֶן מַחְשְׁבֹתָיו וְיָשֹׁב אֶל־יְהֹוָה וִירַחֲמֵהוּ וְאֶל־אֱלֹהֵינוּ כִּי־יַרְבֶּה לִסְלוֹחַ׃","en":"Let the wicked forsake his way, and the unrighteous man his thoughts: and let him return unto the LORD, and he will have mercy upon him; and to our God, for he will abundantly pardon."}]});
